// Compare the request adapter against upstream's batched search, including its
// two levels of query quantization. Inputs are generated by smoke.py.
#include "parlay.cpp"
#include <iostream>

template<class Raw, class Exact, class A, class F>
void check(char* base, char* graph, char* queries, bool normalize) {
  Model<Raw, Exact, A, F> model(base, graph, normalize, 2);
  PointRange<Raw> raw(queries);
  if (normalize) for (size_t i = 0; i < raw.size(); ++i) raw[i].normalize();
  PointRange<Exact> q(raw, model.base.params);
  auto aq = convert_query<PointRange<A>>(q, model.admission.params);
  auto fq = filter_query<PointRange<F>>(q, aq, model.filter.params);
  stats<uint32_t> counters(raw.size());
  QueryParams params(5, 32, model.graph.size(), model.graph.max_degree(), 2);
  auto reference = qsearchAll(q, aq, fq, model.graph, model.base, model.admission,
                             model.filter, counters, uint32_t(0), params);
  PointRange<Euclidian_Point<float>> original(queries);
  for (size_t i = 0; i < raw.size(); ++i) {
    std::vector<float> values(original.dimension());
    for (size_t j = 0; j < values.size(); ++j) values[j] = original[i][j];
    uint32_t ids[5];
    model.search(values.data(), values.size(), 5, 32, ids);
    for (size_t j = 0; j < 5; ++j)
      if (ids[j] != reference[i][j]) throw std::runtime_error("request/batch IDs differ");
  }
}
int main(int argc, char** argv) {
  if (argc != 4) return 2;
  using E = Euclidian_Point<float>; using E8 = Euclidian_Point<uint8_t>;
  using E16 = Euclidian_Point<uint16_t>; using J = Euclidean_JL_Sparse_Point<1024>;
  using M = Mips_Point<float>; using M16 = Quantized_Mips_Point<16>;
  using A = Quantized_Mips_Point<8, true, 255>; using MJ = Mips_JL_Sparse_Point<1024>;
  check<E,E,E,E>(argv[1],argv[2],argv[3],false);
  check<E,E8,E8,E8>(argv[1],argv[2],argv[3],false);
  check<E,E16,E8,E8>(argv[1],argv[2],argv[3],false);
  check<E,E16,E8,J>(argv[1],argv[2],argv[3],false);
  check<M,M,M,M>(argv[1],argv[2],argv[3],false);
  check<M,M16,A,A>(argv[1],argv[2],argv[3],true);
  check<M,M16,A,MJ>(argv[1],argv[2],argv[3],true);
  std::cout << "7 ParlayANN request/batch quantization recipes matched\n";
}
